import numpy as np
def f(g):
    g=[row[:] for row in g]; h,w=len(g),len(g[0])
    bg=g[0][0]
    # find separator: uniform full row or column of a color != bg
    sep=None; val=None; axis=None
    for r in range(h):
        if len(set(g[r]))==1 and g[r][0]!=bg: sep=('row',r); val=g[r][0]; axis='row'
    if sep is None:
        for c in range(w):
            cs=set(g[r][c] for r in range(h))
            if len(cs)==1 and next(iter(cs))!=bg: sep=('col',c); val=next(iter(cs)); axis='col'
    out=[[x for x in row] for row in g]
    cells=[(r,c) for r in range(h) for c in range(w) if g[r][c]!=bg and g[r][c]!=val]
    if axis=='row':
        pos=sep[1]; minr=min(r for r,c in cells); maxr=max(r for r,c in cells)
        if pos < minr: d=pos-minr+1   # move up to touch sep (top -> pos+1)
        else:          d=pos-maxr-1   # move down to touch sep (bottom -> pos-1)
        far = maxr+d if pos>maxr else minr+d  # edge of object farthest from sep after move
        L=far+1
        for r,c in cells:
            out[r+d][c]=g[r][c]
        for c in range(w): out[L][c]=8
    else:
        pos=sep[1]; minc=min(c for r,c in cells); maxc=max(c for r,c in cells)
        if pos > maxc: d=pos-maxc-1     # move right to touch sep
        else: d=pos-minc+1              # move left to touch sep
        far = minc+d if pos>maxc else maxc+d
        L=far-1
        for r,c in cells:
            out[r][c+d]=g[r][c]
        for r in range(h): out[r][L]=8
    return out
